const ExportTemplateSchema = z
  .object({
    as_attachment: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'Download file as attachment', title: 'As attachment' }),
    content_types: z.array(z.string()).superRefine((items, ctx) => {
      const seen = new Map()
      for (const [i, val] of items.entries()) {
        const key = JSON.stringify(val)
        if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
        else seen.set(key, i)
      }
    }),
    created: z.iso
      .datetime({ offset: true })
      .nullable()
      .exactOptional()
      .openapi({ readOnly: true, title: 'Created' }),
    description: z.string().max(200).exactOptional().openapi({ title: 'Description' }),
    display: z.string().exactOptional().openapi({ readOnly: true, title: 'Display' }),
    file_extension: z
      .string()
      .max(15)
      .exactOptional()
      .openapi({
        description: 'Extension to append to the rendered filename',
        title: 'File extension',
      }),
    id: z.int().exactOptional().openapi({ readOnly: true, title: 'ID' }),
    last_updated: z.iso
      .datetime({ offset: true })
      .nullable()
      .exactOptional()
      .openapi({ readOnly: true, title: 'Last updated' }),
    mime_type: z
      .string()
      .max(50)
      .exactOptional()
      .openapi({ description: 'Defaults to <code>text/plain</code>', title: 'MIME type' }),
    name: z.string().min(1).max(100).openapi({ title: 'Name' }),
    template_code: z
      .string()
      .min(1)
      .openapi({
        description:
          'Jinja2 template code. The list of objects being exported is passed as a context variable named <code>queryset</code>.',
        title: 'Template code',
      }),
    url: z.url().exactOptional().openapi({ readOnly: true, title: 'Url' }),
  })
  .openapi({ required: ['content_types', 'name', 'template_code'] })
  .openapi('ExportTemplate')

