const WritableObjectPermissionSchema = z
  .object({
    actions: z
      .array(z.string().min(1).max(30).openapi({ title: 'Actions' }))
      .openapi({ description: 'The list of actions granted by this permission' }),
    constraints: z
      .object({})
      .nullable()
      .exactOptional()
      .openapi({
        description: 'Queryset filter matching the applicable objects of the selected type(s)',
        title: 'Constraints',
      }),
    description: z.string().max(200).exactOptional().openapi({ title: 'Description' }),
    display: z.string().exactOptional().openapi({ readOnly: true, title: 'Display' }),
    enabled: z.boolean().exactOptional().openapi({ title: 'Enabled' }),
    groups: z
      .array(z.int())
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .exactOptional(),
    id: z.int().exactOptional().openapi({ readOnly: true, title: 'ID' }),
    name: z.string().min(1).max(100).openapi({ title: 'Name' }),
    object_types: z.array(z.string()).superRefine((items, ctx) => {
      const seen = new Map()
      for (const [i, val] of items.entries()) {
        const key = JSON.stringify(val)
        if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
        else seen.set(key, i)
      }
    }),
    url: z.url().exactOptional().openapi({ readOnly: true, title: 'Url' }),
    users: z
      .array(z.int())
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .exactOptional(),
  })
  .openapi({ required: ['name', 'object_types', 'actions'] })
  .openapi('WritableObjectPermission')

